--绘制排名信息
function UIWorldBossUnLockNode:FillRankInfo()
    local info = worldBossComponent:GetCurRankInfo()
    if not info then
        return
    end
    if checkNumber(info.ranking) == 0 then
        CfUtils.FillText(self.TextNO, "--")
        CfUtils.FillText(self.TextNumber, "")
    else
        local num = worldBossComponent:GetCurPercentageRank()
        --不在100名内
        if num > 0 then
            local vo = self:GetRankVo(num)
            if vo then
                if checkNumber(vo.id) == 8 then
                    CfUtils.FillText(self.TextNO, "80%+")
                else
                    CfUtils.FillText(self.TextNO, vo.name)
                end
            end
        else
            CfUtils.FillText(self.TextNO, info.ranking)
        end

        CfUtils.FillText(self.TextNumber, info.hurt)
    end
end

function UIWorldBossUnLockNode:GetRankVo(num)
    local t = CfUtils.GetCf(AutoIds.IdSetting978, "WorldBossRankRewardVo", true)
    if not t then
        return nil
    end
    for k, v in pairs(t) do
        if checkNumber(v.type) == 2 then
            if num >= checkNumber(v.upperLimit) and num <= checkNumber(v.lowerLimit) then
                return v
            end
        end
    end
    return nil
end

--绘制buff信息
function UIWorldBossUnLockNode:FillBuffInfo()
    local num = worldBossComponent:GetBuyBuffFreeNum()
    KTool.SetActive(self.TxtNum, num <= 0)
    KTool.SetActive(self.BtnLogisticsText, num > 0)
    if num <= 0 then
        local consumId = QuestConfMgr:GetInstance():GetWorldBossBuffRefreshConsumeId()
        local num = QuestConfMgr:GetInstance():GetWorldBossBuffRefreshConsumeNum()
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(consumId)
        if vo then
            CfUtils.FillText(self.TxtNum, localize("_num_   ", {_num_ = num}))
            CfUtils.FillImage(self.ImgMoney, vo.photoPath)
        end
    else
        CfUtils.FillText(self.BtnLogisticsText, localize("免费X_num_", {_num_ = num}))
    end
    local buffs = worldBossComponent:GetCurBossBuffs()

    --self:FillBuffIcons(buffs)
    --self:FillBuffDescs(buffs)
end

function UIWorldBossUnLockNode:FillBuffIcons(data)
    if not data then
        return
    end

    for i = 1, #data do
        local go = self.LogisticsIconGroup.transform:Find("buff"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.Imgbg, self.LogisticsIconGroup)
            go.name = "buff"..i
        end
        local vo = QuestConfMgr:GetInstance():GetWorldBossBuffTypeVo(data[i].type)
        if vo then
            CfUtils.FillImage(go.transform:Find("ImgIcon"), vo.icon)
        end
        KTool.SetActive(go, true)
    end

    if #data < self.LogisticsIconGroup.childCount then
        for i = #data + 1, self.LogisticsIconGroup.childCount do
            local go = self.LogisticsIconGroup.transform:Find("buff"..i)
            if go then
                KTool.SetActive(go, false)
            end
        end
    end
end

function UIWorldBossUnLockNode:FillBuffDescs(data)
    if not data then
        return
    end

    for i = 1, #data do
        local go = self.Content.transform:Find("BuffDesNode"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.BuffDesNode, self.Content)
            go.name = "BuffDesNode"..i
        end
        local tableName = string.format("%sIDGroup", AutoIds.IdSetting972)
        local id = CfUtils.GetStringIdGroupData(tableName, checkNumber(data[i].type).."_"..checkNumber(data[i].targetId))
        local vo = QuestConfMgr:GetInstance():GetWorldBossBuffVo(id)
        if vo then
            CfUtils.FillText(go, vo.desc)
        end
        KTool.SetActive(go, true)
    end

    if #data < self.Content.childCount then
        for i = #data + 1, self.Content.childCount do
            local go = self.Content.transform:Find("BuffDesNode"..i)
            if go then
                KTool.SetActive(go, false)
            end
        end
    end
    local rt = self.Content:GetComponent(typeof(RectTransform))
    CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(rt)
end

