--获取所有的buff
function UIWorldBossUnLockNode:GetAllBuff() 
    if self._buffStr then
        return self._buffStr
    end
    self._buffStr = ""
    local cfDatas = CfUtils.GetCfTable(AutoIds.IdSetting972)
    for k, v in pairs(cfDatas) do
        local WorldBossBuffVo = import("Game.Setting.Vo.WorldBossBuffVo")

        local vo = WorldBossBuffVo.New()
        vo:FillVo(v)
        self._buffStr = self._buffStr..checkString(vo.typeDesc)..":"..checkString(vo.desc).."\n"
    end  
    return self._buffStr
end

--购买buff
function UIWorldBossUnLockNode:OnBtnBuyBuff() 
    local consumId = QuestConfMgr:GetInstance():GetWorldBossBuffRefreshConsumeId()
    local num = QuestConfMgr:GetInstance():GetWorldBossBuffRefreshConsumeNum()
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(consumId)
    if not vo then
        return
    end
    local freeNum = worldBossComponent:GetBuyBuffFreeNum()
    local consumVo = {
        goodsId = vo.id,
        num = num
    }
    if freeNum <= 0 then
        GameUtils.SecondConfirm(localize("消耗_num__name_重新获取补给品嘛(原效果将被替换)", {_num_ = num, _name_ = vo.name}), function()
            if GoodsUtils.GetThingNo(consumVo.goodsId) < num then 
                local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.id)
                GameUtils.Toast(localize("_name_不足", {_name_ = vo.name}))
                return 
            end
            worldBossComponent:WorldBossExtractBuffReq(function()
                self:RefreshBuff()
                GoodsUtils.DrawRewards({
                    {
                        num = -consumVo.num,
                        goodsId = consumVo.goodsId
                    }
                }, true)
            end)
        end, nil, nil, 4, {consumVo})
    else
        GameUtils.SecondConfirm(localize("重新获取补给品嘛\n原本的增益效果将被替换(剩余免费_num_次)", {_num_ = worldBossComponent:GetBuyBuffFreeNum()}), function()
            worldBossComponent:WorldBossExtractBuffReq(function()
                self:RefreshBuff()
                GoodsUtils.DrawRewards({
                    {
                        num = -consumVo.num,
                        goodsId = consumVo.goodsId
                    }
                }, true)
            end)
        end)
    end
end

--刷新buff
function UIWorldBossUnLockNode:RefreshBuff()
    self:FillBuffInfo()

    if IsNull(self.loader) then
        self.loader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/WorldBoss/WorldBossNewBuffGetDialog.prefab", nil, true)
    end
    local go
    if self.loader.IsSuccess then
        go = CfUtils.InstantiateGo(self.loader.ResultObject, self.Root)
    end
    if go then
        local scr = CfUtils.GetLuaScr(go, WorldBossNewBuffGetNode)
        if scr then
            scr:Refresh(worldBossComponent:GetCurBossBuffs())
        end
    end
end

