--编队
function UIWorldBossUnLockNode:OnBtnTeam()
    if not worldBossComponent:IsOpen() then
        GameUtils.Toast(localize("活动未开启"))
        return
    end
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = {levelId = self._curBossPlanVo.range}}, {
        {id = Constants.UITypeIds.UIWorldBossMainDialog}
    })
end

function UIWorldBossUnLockNode:OnDestroy()
    if not isNull(self.loader) then
        self.loader:Release()
        self.loader = nil
    end
    Events.RemoveListener(Constants.EventNames.WorldBossBuffChange, self.EventWorldBossBuffChange)

    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.WorldBossReward)
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIWorldBossUnLockNode
